use std::collections::BTreeSet;

use crate::error::{Detail, Error, Limit, Result};
use crate::presentation::{MAX_BASE, Presentation, uses_only};
use crate::table::{CosetLimit, CosetTable, Footprint, UNDEFINED, index};
use crate::word::Word;

pub(crate) const MAX_SUBGROUP_GENERATORS: usize = 256;
pub(crate) const MAX_EXPANDED: u64 = 1 << 16;
pub(crate) const MAX_TABLE_ENTRIES: u64 = 1 << 24;
pub(crate) const STACK_CAP: usize = 1 << 16;

/// Enumerates the right cosets of the subgroup generated by `subgroup` in
/// the group of `presentation`, and returns their complete coset table in
/// standard form.
///
/// The enumeration is Todd-Coxeter coset enumeration with the Felsch
/// strategy, which defines the first undefined entry of the table, by rows
/// and within a row by columns, and checks the relators that the new entry
/// can affect. It ends with a pass that checks every relator at every coset
/// and every subgroup generator at coset 0, so the returned table is
/// consistent with every relator. The returned table depends only on the
/// arguments. When two calls differ only in the order of the relators or of
/// the subgroup generators and both return a table, the two tables are
/// equal.
///
/// Whether a call finishes within `limit` is not invariant in that way. The
/// number of cosets that a call defines can depend on the order, the
/// spelling, and the length of the relators and of the subgroup generators,
/// so one order can finish within a limit at which another order returns
/// [`ErrorKind::CosetLimitReached`](crate::ErrorKind::CosetLimitReached).
///
/// An empty `subgroup` is the trivial subgroup, so the index of the returned
/// table is then the order of the group. No bound on the time of a call
/// follows from the limits: `limit` bounds the cosets that the call defines
/// and its memory, and not the work that it does for each coset, which grows
/// with the number of letters of the relators.
///
/// # Examples
///
/// ```
/// use escher_group::{CosetLimit, ErrorKind, conway_presentation, enumerate};
/// use escher_signature::Signature;
///
/// let signature: Signature = "*532".parse()?;
/// let presentation = conway_presentation(&signature)?;
/// let table = enumerate(&presentation, &[], CosetLimit::DEFAULT)?;
/// assert_eq!(table.index(), 120);
///
/// let small = CosetLimit::new(100)?;
/// let kind = enumerate(&presentation, &[], small).map_err(|error| error.kind());
/// assert_eq!(kind, Err(ErrorKind::CosetLimitReached));
/// # Ok::<(), Box<dyn std::error::Error>>(())
/// ```
///
/// # Errors
///
/// Returns the first of these errors, checked in this order before the
/// enumeration allocates its table:
///
/// - [`ErrorKind::LimitExceeded`](crate::ErrorKind::LimitExceeded) when
///   `subgroup` has more than 256 words.
/// - [`ErrorKind::LimitExceeded`](crate::ErrorKind::LimitExceeded) for the
///   first word of `subgroup` with more than 4096 letters, and
///   [`ErrorKind::InvalidWord`](crate::ErrorKind::InvalidWord) for the first
///   word that uses a generator that the presentation does not have, checked
///   word by word.
/// - [`ErrorKind::LimitExceeded`](crate::ErrorKind::LimitExceeded) when the
///   relators written out with their exponents have more than 65536 letters
///   in total.
/// - [`ErrorKind::LimitExceeded`](crate::ErrorKind::LimitExceeded) when
///   `limit` times twice the number of generators is more than 16777216.
///
/// Returns an [`Error`] of kind
/// [`ErrorKind::CosetLimitReached`](crate::ErrorKind::CosetLimitReached) when
/// the enumeration has defined `limit` cosets and needs another. A larger
/// limit may or may not let it finish.
pub fn enumerate(
    presentation: &Presentation,
    subgroup: &[Word],
    limit: CosetLimit,
) -> Result<CosetTable> {
    run(presentation, subgroup, limit, STACK_CAP).0
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct Stats {
    pub(crate) defined: u32,
    pub(crate) closing_changes: u32,
    pub(crate) largest_stack: usize,
    pub(crate) coincidences: u64,
    pub(crate) late_gaps: u32,
    pub(crate) fill_steps: u64,
    pub(crate) table_capacity: usize,
    pub(crate) parent_capacity: usize,
    pub(crate) queue_capacity: usize,
    pub(crate) relabelling: Footprint,
}

pub(crate) fn run(
    presentation: &Presentation,
    subgroup: &[Word],
    limit: CosetLimit,
    stack_cap: usize,
) -> (Result<CosetTable>, Stats) {
    let prepared = match prepare(presentation, subgroup, limit) {
        Ok(prepared) => prepared,
        Err(error) => return (Err(error), Stats::default()),
    };
    let mut state = State::new(&prepared, limit.get(), stack_cap);
    match state.execute(&prepared.subgroup) {
        Ok(()) => {
            let (table, counts) = state.into_table();
            (Ok(table), counts)
        }
        Err(LimitReached) => (
            Err(Error::enumerate(Detail::CosetLimitReached(limit.get()))),
            state.counts(),
        ),
    }
}

pub(crate) struct Prepared {
    pub(crate) columns: usize,
    pub(crate) data: Vec<u16>,
    pub(crate) relators: Vec<Span>,
    pub(crate) lists: Vec<Vec<Span>>,
    one_letter: Vec<u16>,
    subgroup: Vec<Vec<u16>>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Span {
    start: u32,
    len: u32,
}

impl Span {
    pub(crate) fn letters(self, data: &[u16]) -> &[u16] {
        let start = index(self.start);
        data.get(start..start + index(self.len)).unwrap_or_default()
    }

    fn doubled(self, data: &[u16]) -> &[u16] {
        let start = index(self.start);
        data.get(start..start + 2 * index(self.len))
            .unwrap_or_default()
    }
}

fn check_limits(presentation: &Presentation, subgroup: &[Word], limit: CosetLimit) -> Result<()> {
    let generators = presentation.generator_count();
    if subgroup.len() > MAX_SUBGROUP_GENERATORS {
        return Err(Error::enumerate(Detail::LimitExceeded(
            Limit::SubgroupGenerators,
        )));
    }
    for (position, word) in (1..).zip(subgroup) {
        if word.len() > MAX_BASE {
            return Err(Error::enumerate(Detail::LimitExceeded(
                Limit::SubgroupLetters(position),
            )));
        }
        if !uses_only(word, generators) {
            return Err(Error::enumerate(Detail::SubgroupLetter(position)));
        }
    }
    check_expanded(presentation).map_err(Error::enumerate)?;
    let columns = 2 * generators;
    let entries = u64::from(limit.get()).saturating_mul(u64::try_from(columns).unwrap_or(u64::MAX));
    if entries > MAX_TABLE_ENTRIES {
        return Err(Error::enumerate(Detail::LimitExceeded(
            Limit::TableEntries {
                limit: limit.get(),
                columns,
            },
        )));
    }
    Ok(())
}

pub(crate) fn check_expanded(presentation: &Presentation) -> core::result::Result<(), Detail> {
    let mut expanded: u64 = 0;
    for relator in presentation.relators() {
        expanded = expanded.saturating_add(relator.expanded_len());
    }
    if expanded > MAX_EXPANDED {
        return Err(Detail::LimitExceeded(Limit::Expanded(expanded)));
    }
    Ok(())
}

pub(crate) fn prepare(
    presentation: &Presentation,
    subgroup: &[Word],
    limit: CosetLimit,
) -> Result<Prepared> {
    check_limits(presentation, subgroup, limit)?;
    Ok(build(presentation, subgroup))
}

pub(crate) fn build(presentation: &Presentation, subgroup: &[Word]) -> Prepared {
    let columns = 2 * presentation.generator_count();
    let mut data = Vec::new();
    let mut words = Vec::new();
    let mut relators = Vec::new();
    let mut one_letter = Vec::new();
    for relator in presentation.relators() {
        let base = relator.base().letters();
        let expanded: Word = (0..relator.exponent())
            .flat_map(|_| base.iter().copied())
            .collect();
        let cyclic: Vec<u16> = expanded
            .cyclically_reduced()
            .letters()
            .iter()
            .map(|letter| letter.column())
            .collect();
        match cyclic.as_slice() {
            [] => continue,
            [column] => one_letter.push(*column),
            _ => {}
        }
        let forward = push_doubled(&mut data, cyclic.iter().copied());
        let backward = push_doubled(&mut data, cyclic.iter().rev().map(|column| column ^ 1));
        relators.push(forward);
        words.push(forward);
        words.push(backward);
    }

    let mut lists = vec![Vec::new(); columns];
    let mut seen: BTreeSet<&[u16]> = BTreeSet::new();
    for &word in &words {
        let doubled = word.doubled(&data);
        let len = index(word.len);
        let least = least_rotation(doubled, len);
        if !seen.insert(&doubled[least..least + len]) {
            continue;
        }
        for (offset, &first) in (0..).zip(&doubled[..period(&doubled[..len])]) {
            let conjugate = Span {
                start: word.start + offset,
                len: word.len,
            };
            if let Some(list) = lists.get_mut(usize::from(first)) {
                list.push(conjugate);
            }
        }
    }

    let subgroup = subgroup
        .iter()
        .map(|word| {
            word.letters()
                .iter()
                .map(|letter| letter.column())
                .collect()
        })
        .collect();
    Prepared {
        columns,
        data,
        relators,
        lists,
        one_letter,
        subgroup,
    }
}

fn push_doubled(data: &mut Vec<u16>, letters: impl Iterator<Item = u16> + Clone) -> Span {
    let start = data.len();
    data.extend(letters.clone());
    let len = data.len() - start;
    data.extend(letters);
    Span {
        start: u32::try_from(start).unwrap_or(u32::MAX),
        len: u32::try_from(len).unwrap_or(u32::MAX),
    }
}

fn least_rotation(doubled: &[u16], len: usize) -> usize {
    let (mut first, mut second, mut matched) = (0, 1, 0);
    while first < len && second < len && matched < len {
        let left = doubled[first + matched];
        let right = doubled[second + matched];
        if left == right {
            matched += 1;
            continue;
        }
        if left > right {
            first += matched + 1;
        } else {
            second += matched + 1;
        }
        if first == second {
            second += 1;
        }
        matched = 0;
    }
    first.min(second)
}

fn period(word: &[u16]) -> usize {
    let len = word.len();
    let mut border = vec![0; len];
    let mut matched = 0;
    for position in 1..len {
        while matched > 0 && word[position] != word[matched] {
            matched = border[matched - 1];
        }
        if word[position] == word[matched] {
            matched += 1;
        }
        border[position] = matched;
    }
    let shortest = len - border.last().copied().unwrap_or(0);
    if len.is_multiple_of(shortest) {
        shortest
    } else {
        len
    }
}

struct LimitReached;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Scan {
    Correct,
    Incomplete { coset: u32, column: u16 },
    Deduced,
    Coincidence(u32, u32),
}

struct State<'a> {
    prepared: &'a Prepared,
    limit: u32,
    stack_cap: usize,
    table: Vec<u32>,
    parent: Vec<u32>,
    stack: Vec<(u32, u16)>,
    queue: Vec<u32>,
    queue_head: usize,
    cursor: (u32, usize),
    stats: Stats,
}

impl<'a> State<'a> {
    fn new(prepared: &'a Prepared, limit: u32, stack_cap: usize) -> Self {
        Self {
            prepared,
            limit,
            stack_cap,
            table: vec![UNDEFINED; prepared.columns],
            parent: vec![0],
            stack: Vec::new(),
            queue: Vec::new(),
            queue_head: 0,
            cursor: (0, 0),
            stats: Stats {
                defined: 1,
                ..Stats::default()
            },
        }
    }

    fn execute(&mut self, subgroup: &[Vec<u16>]) -> core::result::Result<(), LimitReached> {
        self.one_letter_rule(0);
        self.process_deductions();
        for word in subgroup {
            self.scan_and_fill(word)?;
            self.process_deductions();
        }
        loop {
            while let Some((coset, column)) = self.next_gap() {
                self.define(coset, column)?;
                self.process_deductions();
            }
            if !self.closing_pass(subgroup) {
                return Ok(());
            }
            self.process_deductions();
        }
    }

    fn columns(&self) -> usize {
        self.prepared.columns
    }

    fn counts(&self) -> Stats {
        Stats {
            table_capacity: self.table.capacity(),
            parent_capacity: self.parent.capacity(),
            queue_capacity: self.queue.capacity(),
            ..self.stats
        }
    }

    fn rows(&self) -> u32 {
        u32::try_from(self.parent.len()).unwrap_or(u32::MAX)
    }

    fn slot(&self, coset: u32, column: u16) -> usize {
        index(coset) * self.columns() + usize::from(column)
    }

    fn get(&self, coset: u32, column: u16) -> u32 {
        self.table
            .get(self.slot(coset, column))
            .copied()
            .unwrap_or(UNDEFINED)
    }

    fn set(&mut self, coset: u32, column: u16, value: u32) {
        let slot = self.slot(coset, column);
        if let Some(entry) = self.table.get_mut(slot) {
            *entry = value;
        }
    }

    fn is_live(&self, coset: u32) -> bool {
        self.parent.get(index(coset)) == Some(&coset)
    }

    fn find(&mut self, coset: u32) -> u32 {
        let mut root = coset;
        while let Some(&up) = self.parent.get(index(root)) {
            if up == root {
                break;
            }
            root = up;
        }
        let mut current = coset;
        while current != root {
            let Some(up) = self.parent.get_mut(index(current)) else {
                break;
            };
            current = core::mem::replace(up, root);
        }
        root
    }

    fn push(&mut self, coset: u32, column: u16) {
        self.stack.push((coset, column));
        self.stats.largest_stack = self.stats.largest_stack.max(self.stack.len());
    }

    fn write(&mut self, coset: u32, column: u16, target: u32) {
        self.set(coset, column, target);
        self.set(target, column ^ 1, coset);
        self.push(coset, column);
    }

    fn one_letter_rule(&mut self, coset: u32) {
        let prepared = self.prepared;
        for &column in &prepared.one_letter {
            for column in [column, column ^ 1] {
                if self.get(coset, column) == UNDEFINED {
                    self.set(coset, column, coset);
                    self.push(coset, column);
                }
            }
        }
    }

    fn define(&mut self, coset: u32, column: u16) -> core::result::Result<u32, LimitReached> {
        let rows = self.rows();
        if rows >= self.limit {
            return Err(LimitReached);
        }
        let columns = self.columns();
        let most = index(self.limit);
        grow_within(&mut self.table, columns, most * columns);
        self.table.resize(self.table.len() + columns, UNDEFINED);
        grow_within(&mut self.parent, 1, most);
        self.parent.push(rows);
        self.stats.defined = rows + 1;
        self.set(coset, column, rows);
        self.set(rows, column ^ 1, coset);
        self.one_letter_rule(rows);
        self.push(coset, column);
        Ok(rows)
    }

    fn scan(&mut self, coset: u32, word: &[u16]) -> Scan {
        let mut forward = coset;
        let mut first = 0;
        while let Some(&column) = word.get(first) {
            let next = self.get(forward, column);
            if next == UNDEFINED {
                break;
            }
            forward = next;
            first += 1;
        }
        if first == word.len() {
            return if forward == coset {
                Scan::Correct
            } else {
                Scan::Coincidence(forward, coset)
            };
        }
        let mut backward = coset;
        let mut end = word.len();
        while end > first {
            let next = self.get(backward, word[end - 1] ^ 1);
            if next == UNDEFINED {
                break;
            }
            backward = next;
            end -= 1;
        }
        if end == first {
            return if forward == backward {
                Scan::Correct
            } else {
                Scan::Coincidence(forward, backward)
            };
        }
        if end == first + 1 {
            self.write(forward, word[first], backward);
            return Scan::Deduced;
        }
        Scan::Incomplete {
            coset: forward,
            column: word[first],
        }
    }

    fn settle(&mut self, scan: Scan) {
        if let Scan::Coincidence(first, second) = scan {
            self.coincidence(first, second);
        }
    }

    fn scan_and_fill(&mut self, word: &[u16]) -> core::result::Result<(), LimitReached> {
        let (mut forward, mut first) = (0, 0);
        let (mut backward, mut end) = (0, word.len());
        loop {
            forward = self.find(forward);
            backward = self.find(backward);
            while let Some(&column) = word.get(first).filter(|_| first < end) {
                let next = self.get(forward, column);
                if next == UNDEFINED {
                    break;
                }
                forward = next;
                first += 1;
                self.stats.fill_steps += 1;
            }
            while end > first {
                let next = self.get(backward, word[end - 1] ^ 1);
                if next == UNDEFINED {
                    break;
                }
                backward = next;
                end -= 1;
                self.stats.fill_steps += 1;
            }
            if end == first {
                if forward != backward {
                    self.coincidence(forward, backward);
                }
                return Ok(());
            }
            if end == first + 1 {
                self.write(forward, word[first], backward);
                return Ok(());
            }
            self.define(forward, word[first])?;
            self.process_deductions();
        }
    }

    fn merge(&mut self, first: u32, second: u32) {
        let first = self.find(first);
        let second = self.find(second);
        if first != second {
            let (kept, removed) = (first.min(second), first.max(second));
            if let Some(up) = self.parent.get_mut(index(removed)) {
                *up = kept;
            }
            let most = index(self.limit);
            grow_within(&mut self.queue, 1, most);
            self.queue.push(removed);
            self.stats.coincidences += 1;
        }
    }

    fn coincidence(&mut self, first: u32, second: u32) {
        self.merge(first, second);
        while let Some(&gamma) = self.queue.get(self.queue_head) {
            self.queue_head += 1;
            for column in 0..self.columns() {
                let column = u16::try_from(column).unwrap_or(u16::MAX);
                let delta = self.get(gamma, column);
                if delta == UNDEFINED {
                    continue;
                }
                self.set(delta, column ^ 1, UNDEFINED);
                let mu = self.find(gamma);
                let nu = self.find(delta);
                let image = self.get(mu, column);
                let back = self.get(nu, column ^ 1);
                if image != UNDEFINED {
                    self.merge(nu, image);
                } else if back != UNDEFINED {
                    self.merge(mu, back);
                } else {
                    self.write(mu, column, nu);
                }
            }
        }
        self.queue.clear();
        self.queue_head = 0;
    }

    fn process_deductions(&mut self) {
        loop {
            if self.stack.len() >= self.stack_cap {
                self.stack.clear();
                self.lookahead();
                continue;
            }
            let Some((first, column)) = self.stack.pop() else {
                return;
            };
            self.scan_list(first, column);
            if self.is_live(first) {
                let second = self.get(first, column);
                if second != UNDEFINED {
                    self.scan_list(second, column ^ 1);
                }
            }
        }
    }

    fn scan_list(&mut self, coset: u32, column: u16) {
        let prepared = self.prepared;
        let Some(list) = prepared.lists.get(usize::from(column)) else {
            return;
        };
        for span in list {
            if !self.is_live(coset) {
                return;
            }
            let word = span.letters(&prepared.data);
            let scan = self.scan(coset, word);
            self.settle(scan);
        }
    }

    fn lookahead(&mut self) {
        let prepared = self.prepared;
        for coset in 0..self.rows() {
            for span in &prepared.relators {
                if !self.is_live(coset) {
                    break;
                }
                let word = span.letters(&prepared.data);
                let scan = self.scan(coset, word);
                self.settle(scan);
            }
        }
    }

    fn next_gap(&mut self) -> Option<(u32, u16)> {
        let (mut row, mut column) = self.cursor;
        while row < self.rows() {
            if self.is_live(row) {
                while column < self.columns() {
                    let letter = u16::try_from(column).unwrap_or(u16::MAX);
                    if self.get(row, letter) == UNDEFINED {
                        self.cursor = (row, column);
                        return Some((row, letter));
                    }
                    column += 1;
                }
            }
            row += 1;
            column = 0;
        }
        self.cursor = (row, 0);
        for row in 0..self.rows() {
            if !self.is_live(row) {
                continue;
            }
            for column in 0..self.columns() {
                let letter = u16::try_from(column).unwrap_or(u16::MAX);
                if self.get(row, letter) == UNDEFINED {
                    self.stats.late_gaps += 1;
                    self.cursor = (row, column);
                    return Some((row, letter));
                }
            }
        }
        None
    }

    fn closing_pass(&mut self, subgroup: &[Vec<u16>]) -> bool {
        let prepared = self.prepared;
        let mut changed = false;
        for coset in 0..self.rows() {
            for span in &prepared.relators {
                if !self.is_live(coset) {
                    break;
                }
                let word = span.letters(&prepared.data);
                let scan = self.scan(coset, word);
                if scan != Scan::Correct {
                    changed = true;
                    self.stats.closing_changes += 1;
                    self.settle(scan);
                }
            }
        }
        for word in subgroup {
            let scan = self.scan(0, word);
            if scan != Scan::Correct {
                changed = true;
                self.stats.closing_changes += 1;
                self.settle(scan);
            }
        }
        changed
    }

    fn into_table(mut self) -> (CosetTable, Stats) {
        let mut counts = self.counts();
        self.stack = Vec::new();
        self.queue = Vec::new();
        for coset in 0..self.rows() {
            self.find(coset);
        }
        let parent = &self.parent;
        let (table, footprint) =
            CosetTable::standard(self.columns(), self.parent.len(), &self.table, |coset| {
                parent.get(index(coset)).copied().unwrap_or(UNDEFINED)
            });
        counts.relabelling = footprint;
        (table, counts)
    }
}

pub(crate) fn grow_within<T>(vector: &mut Vec<T>, extra: usize, most: usize) {
    let needed = vector.len() + extra;
    if needed > vector.capacity() {
        let target = (2 * vector.len()).max(needed).min(most).max(needed);
        vector.reserve_exact(target - vector.len());
    }
}

#[cfg(test)]
mod tests {
    use proptest::prelude::prop_assert_eq;
    use proptest::proptest;

    use super::{STACK_CAP, Stats, prepare, run};
    use crate::common::{FIXTURES, conway, letters, limit, names, random_presentation};
    use crate::enumerate::enumerate;
    use crate::error::ErrorKind;
    use crate::presentation::{Presentation, Relator};
    use crate::table::{CosetLimit, CosetTable, Footprint};
    use crate::word::{Letter, Word};

    fn finished(
        presentation: &Presentation,
        subgroup: &[Word],
        stack_cap: usize,
    ) -> (CosetTable, Stats) {
        let (result, stats) = run(presentation, subgroup, CosetLimit::DEFAULT, stack_cap);
        (result.expect("the enumeration finishes"), stats)
    }

    #[test]
    fn one_letter_relators_define_exactly_the_group_order() {
        for (signature, order) in [("*532", 120), ("x", 2), ("*", 2)] {
            let (table, stats) = finished(&conway(signature), &[], STACK_CAP);
            assert_eq!(table.index(), order, "{signature}");
            assert_eq!(
                stats.defined,
                u32::try_from(order).expect("small"),
                "{signature}"
            );
        }
    }

    #[test]
    fn conjugate_lists_hold_each_distinct_conjugate_once() {
        let [r1, r2] = [0, 1].map(Letter::generator);
        let relator = Relator::new(letters(&[r1, r2]), 1000).expect("the relator is valid");
        let presentation = Presentation::new(names(2), vec![relator]).expect("it is valid");
        let prepared =
            prepare(&presentation, &[], CosetLimit::DEFAULT).expect("it is in the limits");
        let sizes: Vec<usize> = prepared.lists.iter().map(Vec::len).collect();
        assert_eq!(sizes, [1, 1, 1, 1]);
    }

    #[test]
    fn stack_cap_one_gives_the_tables_of_the_default_cap() {
        let mut cases: Vec<(String, Presentation, Vec<Word>)> = FIXTURES
            .iter()
            .filter(|fixture| !fixture.source.contains("Cox") && !fixture.source.contains("B_2_4"))
            .map(|fixture| {
                (
                    fixture.source.to_owned(),
                    fixture.presentation(),
                    fixture.subgroup(),
                )
            })
            .collect();
        cases.push(("*532".to_owned(), conway("*532"), Vec::new()));
        for (source, presentation, subgroup) in cases {
            let (default, _) = finished(&presentation, &subgroup, STACK_CAP);
            let (capped, stats) = finished(&presentation, &subgroup, 1);
            assert_eq!(capped, default, "{source}");
            assert_eq!(stats.closing_changes, 0, "{source}");
        }
    }

    #[test]
    fn fixture_rows_have_a_column_for_each_letter() {
        for fixture in FIXTURES {
            for row in fixture.rows {
                assert_eq!(
                    row.len(),
                    2 * fixture.generators.len(),
                    "{}",
                    fixture.source
                );
            }
            assert!(fixture.index >= fixture.rows.len(), "{}", fixture.source);
        }
    }

    #[test]
    fn filling_a_subgroup_generator_reads_each_letter_once() {
        let x = Letter::generator(0);
        let square = Relator::new(letters(&[x]), 2).expect("valid");
        let presentation = Presentation::new(names(1), vec![square]).expect("it is valid");
        let (result, stats) = run(&presentation, &[letters(&[x; 4096])], limit(2), STACK_CAP);
        assert_eq!(result.map(|table| table.index()), Ok(2));
        assert!(stats.fill_steps <= 4096, "{}", stats.fill_steps);
        let cycle = Relator::new(letters(&[x]), 512).expect("valid");
        let presentation = Presentation::new(names(1), vec![cycle]).expect("it is valid");
        let (result, stats) = run(&presentation, &[letters(&[x; 512])], limit(512), STACK_CAP);
        assert_eq!(result.map(|table| table.index()), Ok(512));
        assert!(stats.fill_steps <= 512, "{}", stats.fill_steps);
    }

    #[test]
    fn capacities_stay_within_the_limit() {
        let x = Letter::generator(0);
        let cyclic = Relator::new(letters(&[x]), 600).expect("valid");
        let presentation = Presentation::new(names(1), vec![cyclic]).expect("it is valid");
        let (result, stats) = run(&presentation, &[], limit(600), STACK_CAP);
        assert_eq!(result.map(|table| table.index()), Ok(600));
        assert_eq!(stats.table_capacity, 1200);
        assert_eq!(stats.parent_capacity, 600);
        assert_eq!(
            stats.relabelling,
            Footprint {
                label: 600,
                order: 600,
                entries: 1200
            }
        );
    }

    #[test]
    fn coincidence_queue_stays_within_the_limit() {
        let [x, y] = [0, 1].map(Letter::generator);
        let power = |letter: Letter, other: Letter| {
            let mut base = vec![letter; 8];
            base.push(other.inverse());
            Relator::new(letters(&base), 1).expect("valid")
        };
        let sims = Presentation::new(names(2), vec![power(x, y), power(y, x)]).expect("valid");
        let (result, stats) = run(&sims, &[], limit(138), STACK_CAP);
        assert_eq!(result.map(|table| table.index()), Ok(63));
        assert!(stats.coincidences > 0);
        assert!(stats.queue_capacity <= 138, "{}", stats.queue_capacity);
        assert_eq!(stats.parent_capacity, 138);
        assert_eq!(stats.table_capacity, 552);
    }

    const CAPPED_LIMIT: u32 = 500;

    proptest! {
        #[test]
        fn closing_pass_changes_nothing((presentation, subgroup) in random_presentation()) {
            let (default, stats) = run(&presentation, &subgroup, limit(2000), STACK_CAP);
            prop_assert_eq!(stats.closing_changes, 0);
            prop_assert_eq!(stats.late_gaps, 0);
            let (capped, stats) = run(&presentation, &subgroup, limit(CAPPED_LIMIT), 1);
            prop_assert_eq!(stats.closing_changes, 0);
            prop_assert_eq!(stats.late_gaps, 0);
            if let (Ok(default), Ok(capped)) = (default, capped) {
                prop_assert_eq!(default, capped);
            }
        }
    }

    #[test]
    fn enumerate_checks_the_subgroup_generators() {
        let x = Letter::generator(0);
        let trivial = Relator::new(letters(&[x]), 1).expect("the relator is valid");
        let presentation = Presentation::new(names(1), vec![trivial]).expect("it is valid");
        let kind = |subgroup: &[Word]| {
            enumerate(&presentation, subgroup, CosetLimit::DEFAULT).map_err(|error| error.kind())
        };
        assert_eq!(
            kind(&vec![letters(&[x]); 256]).map(|table| table.index()),
            Ok(1)
        );
        assert_eq!(
            kind(&vec![letters(&[x]); 257]).err(),
            Some(ErrorKind::LimitExceeded)
        );
        assert_eq!(
            kind(&[letters(&[x; 4096])]).map(|table| table.index()),
            Ok(1)
        );
        assert_eq!(
            kind(&[letters(&[x; 4097])]).err(),
            Some(ErrorKind::LimitExceeded)
        );
        let outside = [Word::new(), letters(&[Letter::inverse_of(1)])];
        let error = enumerate(&presentation, &outside, CosetLimit::DEFAULT).err();
        assert_eq!(
            error.map(|error| (error.kind(), error.to_string())),
            Some((
                ErrorKind::InvalidWord,
                "cannot enumerate cosets: subgroup generator 2 uses a generator that the presentation does not have"
                    .to_owned()
            ))
        );
    }

    fn power_of_one_letter(exponent: u32) -> Result<CosetTable, (ErrorKind, String)> {
        let relator = Relator::new(letters(&[Letter::generator(0)]), exponent).expect("valid");
        let presentation = Presentation::new(names(1), vec![relator]).expect("it is valid");
        enumerate(&presentation, &[], limit(1)).map_err(|error| (error.kind(), error.to_string()))
    }

    #[test]
    fn enumerate_accepts_the_expanded_letters_at_their_limit() {
        assert_eq!(
            power_of_one_letter(65536).map(|table| table.index()),
            Err((
                ErrorKind::CosetLimitReached,
                "cannot enumerate cosets: the enumeration defined 1 cosets without finishing"
                    .to_owned()
            ))
        );
    }

    #[test]
    fn enumerate_refuses_more_expanded_letters_than_the_limit() {
        assert_eq!(
            power_of_one_letter(65537).map(|table| table.index()),
            Err((
                ErrorKind::LimitExceeded,
                "cannot enumerate cosets: the relators expand to 65537 letters, more than 65536"
                    .to_owned()
            ))
        );
    }

    #[test]
    fn enumerate_checks_the_table_entries() {
        let trivial = |generators: u8| {
            let relators = (0..generators)
                .map(|index| Relator::new(letters(&[Letter::generator(index)]), 1).expect("valid"))
                .collect();
            Presentation::new(names(usize::from(generators)), relators).expect("it is valid")
        };
        let result = enumerate(&trivial(8), &[], CosetLimit::MAX);
        assert_eq!(result.map(|table| table.index()), Ok(1));
        let error = enumerate(&trivial(9), &[], CosetLimit::MAX).err();
        assert_eq!(
            error.map(|error| (error.kind(), error.to_string())),
            Some((
                ErrorKind::LimitExceeded,
                "cannot enumerate cosets: the coset limit 1048576 times 18 columns is more than 16777216 table entries"
                    .to_owned()
            ))
        );
    }

    #[test]
    fn enumerate_drops_relators_that_reduce_to_the_empty_word() {
        let x = Letter::generator(0);
        let relators = vec![
            Relator::new(letters(&[x, x.inverse()]), 3).expect("valid"),
            Relator::new(letters(&[x]), 2).expect("valid"),
            Relator::new(letters(&[Letter::inverse_of(1)]), 1).expect("valid"),
        ];
        let presentation = Presentation::new(names(2), relators).expect("it is valid");
        let y = Letter::generator(1);
        let table = enumerate(&presentation, &[letters(&[y])], CosetLimit::DEFAULT)
            .expect("the enumeration finishes");
        assert_eq!(table.index(), 2);
        assert_eq!(table.permutation(x), Some(vec![1, 0]));
        assert_eq!(table.permutation(y), Some(vec![0, 1]));
    }
}
